<?php
namespace App\Jobs;
use App\Jobs\Concerns\HasTenantContext; use App\Mail\SalesQuotationMail; use App\Models\{SalesQuotation,SalesQuotationCommunication}; use Illuminate\Bus\{Queueable,Dispatchable}; use Illuminate\Contracts\Queue\ShouldQueue; use Illuminate\Support\Facades\Mail;
final class SendSalesQuotationEmail implements ShouldQueue { use Dispatchable,Queueable,HasTenantContext; public function __construct(string $tenantId,public readonly string $quotationId,public readonly string $communicationId,public readonly string $messageText){$this->tenantId=$tenantId;} public function handle():void{$c=SalesQuotationCommunication::where('tenant_id',$this->tenantId)->findOrFail($this->communicationId);$q=SalesQuotation::where('tenant_id',$this->tenantId)->with(['items','customer'])->findOrFail($this->quotationId);$c->update(['state'=>'attempted','attempted_at'=>now()]);Mail::to($c->recipient)->send(new SalesQuotationMail($q,$this->messageText));} public function failed(\Throwable $e):void{SalesQuotationCommunication::where('tenant_id',$this->tenantId)->whereKey($this->communicationId)->update(['state'=>'failed','failure_reason'=>'Delivery attempt failed']);} }
